    static TrainerEndTurnTest.Config config(String id){var c=new TrainerEndTurnTest.Config();c.id=id;c.trainer=GeneratedRuleBatch8Test.trainer(id);c.definition=BundledRules.loadCardDefinitions().find(id).orElseThrow();return c;}
