    public static void main(String[] args){printed();counts();nonmatchingAndEmpty();eligibility();authority();privacyAndSession();stale();repeated();System.out.println("GeneratedRuleBatch65Test passed: both actual Misty Supporters, Basic Water only,0/1/4 and short search to one Active/Bench, shuffle after attachment, zero-selection turn end, empty-deck eligibility, first-turn/quota, current target authority, private search/stale/replay rejection and independent later uses");}
    static void printed(){for(String id:PRINTS){var c=config(id);var d=c.definition;check(d.effectSupport()==EffectSupport.SUPPORTED&&d.category()==CardCategory.TRAINER&&d.trainerCategory()==TrainerCategory.SUPPORTER&&d.copyLimit()==4&&d.regulationMark().equals("J"),"Actual printed metadata changed "+id);check(c.trainer.endsTurn()&&c.trainer.category()==TrainerCategory.SUPPORTER&&TrainerProgramRules.unsupportedReason(c.trainer.effectProgram()).isEmpty(),"Actual complete program absent");var e=c.trainer.effectProgram().triggers().getFirst().effects().getFirst();var a=AttachEnergyEffect.from(e);check(a.source()==EffectTargetResolution.Zone.DECK&&a.basicEnergyTypes().equals(Set.of(EnergyType.WATER))&&a.distribution()==AttachEnergyEffect.Distribution.SAME_TARGET&&a.policy().maxCards()==4&&a.policy().minCards()==0,"Actual attachment restrictions lost");}}
    static void counts(){for(String id:PRINTS)for(int count:List.of(0,1,4))for(boolean bench:List.of(false,true)){
        var m=game(id);int turn=m.turnNumber(),rng=m.randomTranscript().size();var before=m.privateView(A);var other=m.privateView(B);UUID host=bench?TrainerEndTurnTest.bench(m,A):TrainerEndTurnTest.active(m,A);var used=play(m,id);var p=m.effectCardPrompt(A);
        check(p.minimum()==0&&p.maximum()==4&&new HashSet<>(p.candidates()).equals(new HashSet<>(water(m))),"Actual candidate filter/limits");var picked=p.candidates().subList(0,count);check(m.currentPlayer().equals(A)&&m.privateView(A).deck().equals(before.deck()),"Search mutated deck or ended turn");
        m.submitEffectCards(A,p.resolutionId(),p.step(),picked.stream().map(CardInstance::instanceId).toList());if(count>0){check(m.currentPlayer().equals(A)&&m.privateView(A).deck().equals(before.deck())&&m.randomTranscript().size()==rng,"Selection moved/shuffled before host");var target=m.effectAttachmentPrompt(A);check(target.targets().size()==2&&new HashSet<>(target.targets()).equals(Set.of(TrainerEndTurnTest.active(m,A),TrainerEndTurnTest.bench(m,A))),"Attachment targets leak opponent field");TrainerEndTurnTest.target(m,A,host);}
        TrainerEndTurnTest.finished(m,turn);var view=host.equals(TrainerEndTurnTest.active(m,A))?m.activePokemonView(A):m.benchPokemonView(A).getFirst();check(view.attachedEnergyIds().equals(picked.stream().map(CardInstance::instanceId).toList()),"Selected Energy split/lost/wrong host");
        var remaining=new HashSet<>(before.deck());remaining.removeAll(picked);check(new HashSet<>(m.privateView(A).deck()).equals(remaining)&&m.privateView(A).hand().size()==before.hand().size()-1&&m.privateView(A).discard().contains(used),"Incorrect physical zones after completed Supporter");check(m.randomTranscript().size()-rng==Math.max(0,remaining.size()-1),"Deck shuffled more/less than once");check(m.privateView(B).hand().size()==other.hand().size()+1,"Next turn missing draw");atomic(m,()->m.submitEffectCards(A,p.resolutionId(),p.step(),picked.stream().map(CardInstance::instanceId).toList()));
    }
        var m=game(PRINTS.getFirst());retainWater(m,1);int turn=m.turnNumber();play(m,PRINTS.getFirst());check(m.effectCardPrompt(A).candidates().size()==1,"Short search added nonmatching cards");TrainerEndTurnTest.select(m,1);TrainerEndTurnTest.target(m,A,TrainerEndTurnTest.active(m,A));TrainerEndTurnTest.finished(m,turn);
    }
    static void nonmatchingAndEmpty(){for(String id:PRINTS){var m=game(id);retainWater(m,0);check(!m.privateView(A).deck().isEmpty(),"Need nonempty hidden deck");int turn=m.turnNumber();play(m,id);check(!m.hasPendingEffectChoice(),"No candidates opened unusable prompt");TrainerEndTurnTest.finished(m,turn);var n=game(id);n.discardTopDeckCardsByEffect(A,A,n.privateView(A).deck().size());unavailable(n,id);}}
    static void eligibility(){for(String id:PRINTS){var c=config(id);c.later=false;var m=TrainerEndTurnTest.game(c);unavailable(m,id);m.endTurn(A);m.endTurn(B);var support=TrainerEndTurnTest.hand(m,A,"support");m.playTrainer(A,support.instanceId(),null);unavailable(m,id);}}
    static void authority(){var id=PRINTS.getFirst();var m=game(id);play(m,id);var p=m.effectCardPrompt(A);UUID one=p.candidates().getFirst().instanceId();for(Runnable r:List.<Runnable>of(()->m.submitEffectCards(B,p.resolutionId(),p.step(),List.of(one)),()->m.submitEffectCards(A,UUID.randomUUID(),p.step(),List.of(one)),()->m.submitEffectCards(A,p.resolutionId(),p.step()+1,List.of(one)),()->m.submitEffectCards(A,p.resolutionId(),p.step(),List.of(one,one)),()->m.submitEffectCards(A,p.resolutionId(),p.step(),p.candidates().stream().limit(5).map(CardInstance::instanceId).toList()),()->m.submitEffectCards(A,p.resolutionId(),p.step(),List.of(TrainerEndTurnTest.hand(m,B,"water").instanceId())),()->m.endTurn(A)))atomic(m,r);
        for(var wrong:m.privateView(A).deck().stream().filter(c->!c.definitionId().equals("water")).toList())atomic(m,()->m.submitEffectCards(A,p.resolutionId(),p.step(),List.of(wrong.instanceId())));
        TrainerEndTurnTest.select(m,4);var host=m.effectAttachmentPrompt(A);atomic(m,()->TrainerEndTurnTest.target(m,B,TrainerEndTurnTest.active(m,B)));atomic(m,()->m.chooseEffectAttachmentTarget(B,host.resolutionId(),host.step(),host.targets().getFirst()));atomic(m,()->m.chooseEffectAttachmentTarget(A,host.resolutionId(),host.step()+1,host.targets().getFirst()));TrainerEndTurnTest.target(m,A,TrainerEndTurnTest.bench(m,A));atomic(m,()->m.chooseEffectAttachmentTarget(A,host.resolutionId(),host.step(),host.targets().getFirst()));
    }
    static void privacyAndSession(){var id=PRINTS.getFirst();var m=game(id);var s=MatchSession.multiplayer(m,A,B);s.addSpectator(WATCH);var v=s.view(A,A);var card=TrainerEndTurnTest.hand(m,A,id);var action=v.options().stream().filter(o->o.cardKeys().contains("hand:"+card.instanceId())).findFirst().orElseThrow();s.submit(A,A,v.revision(),action.index());atomic(m,()->s.submit(A,A,v.revision(),action.index()));var prompt=m.effectCardPrompt(A);for(UUID player:List.of(B,WATCH)){var view=s.view(player,player.equals(B)?B:null);check(view.game().effectSelection()==null,"Private search exposed");String wire=new Gson().toJson(view);for(var hidden:m.privateView(A).deck())check(!wire.contains(hidden.instanceId().toString()),"Deck identity leaked");}check(s.view(A,A).options().stream().noneMatch(o->o.labelZh().equals("结束回合")),"Search offers ordinary end turn");TrainerEndTurnTest.select(m,1);TrainerEndTurnTest.target(m,A,TrainerEndTurnTest.active(m,A));atomic(m,()->m.submitEffectCards(A,prompt.resolutionId(),prompt.step(),List.of()));}
